    internal sealed class CatalogDish
    {
        public CatalogDish(string name, string category, string meals, int price, string region, string description)
        {
            Name = name;
            Category = category;
            Meals = meals;
            Price = price;
            Region = region;
            Description = description;
        }

        public string Name { get; }
        public string Category { get; }
        public string Meals { get; }
        public int Price { get; }
        public string Region { get; }
        public string Description { get; }
    }

