    internal static class FoodCatalogWorld
    {
        private static CatalogDish[] cache;

        public static CatalogDish[] All
        {
            get { return cache ?? (cache = Build()); }
        }

        private static CatalogDish[] Build()
        {
            System.Collections.Generic.List<CatalogDish> list = new System.Collections.Generic.List<CatalogDish>(Rows.Length);
            foreach (string row in Rows)
            {
                string[] p = row.Split('|');
                list.Add(new CatalogDish(p[0], p[1], p[2], int.Parse(p[3]), p[4], p[5]));
            }
            return list.ToArray();
        }

